mapper.sql:
WHERE tenant_id=#{tenantId}
AND (campaign_code LIKE CONCAT('%',#{keyword},'%') OR campaign_name LIKE CONCAT('%',#{keyword},'%'))
AND status=#{status}
AND campaign_type=#{campaignType}

mapper.update:
UPDATE crm_campaign SET campaign_name=#{entity.campaignName},campaign_type=#{entity.campaignType},
  starts_at=#{entity.startsAt},ends_at=#{entity.endsAt},status=#{entity.status},version=version+1
WHERE tenant_id=#{tenantId} AND id=#{entity.id} AND version=#{entity.version}

mapper.sql:
WHERE tenant_id=#{tenantId}
AND (channel_no LIKE CONCAT('%',#{keyword},'%') OR name LIKE CONCAT('%',#{keyword},'%'))
AND status=#{status}
AND business_owner_user_id=#{businessOwnerUserId}

mapper.update:
UPDATE crm_partner_channel SET name=#{entity.name},platform_code=#{entity.platformCode},
  business_owner_user_id=#{entity.businessOwnerUserId},status=#{entity.status},remarks=#{entity.remarks},version=version+1
WHERE tenant_id=#{tenantId} AND id=#{entity.id} AND version=#{entity.version}
